import {
  BoxRenderable,
  InputRenderable,
  SelectRenderable,
  SelectRenderableEvents,
  ScrollBoxRenderable,
  TextRenderable,
  createCliRenderer,
} from "@opentui/core";

import { launchRpcClient } from "../runtime/pi.js";
import { HostController, type HostSurface } from "./host-controller.js";

export type OpenTuiExitAction = "exit" | "shell";

/** Run the alternate OpenTUI host over Pi RPC. `keating shell` remains intact. */
export async function launchOpenTui(cwd: string, initialPrompt?: string): Promise<OpenTuiExitAction> {
  const client = await launchRpcClient(cwd);
  let settle: ((action: OpenTuiExitAction) => void) | null = null;
  let settled = false;
  const result = new Promise<OpenTuiExitAction>((resolve) => { settle = resolve; });
  const renderer = await createCliRenderer({
    exitOnCtrlC: true,
    clearOnShutdown: true,
    backgroundColor: "#11100e",
    onDestroy: () => {
      if (!settled) {
        settled = true;
        settle?.("exit");
      }
      void client.stop();
    },
  });

  const shell = new BoxRenderable(renderer, {
    id: "keating-open-tui",
    width: "100%",
    height: "100%",
    flexDirection: "column",
    padding: 1,
    gap: 1,
    backgroundColor: "#11100e",
  });
  const header = new TextRenderable(renderer, {
    id: "keating-open-tui-header",
    content: "KEATING  ·  collaborative teaching host",
    fg: "#d6a84d",
    height: 1,
  });
  const status = new TextRenderable(renderer, {
    id: "keating-open-tui-status",
    content: "Pi RPC connected  ·  /shell switches to the classic Pi interface",
    fg: "#9d9485",
    height: 1,
  });
  const scroll = new ScrollBoxRenderable(renderer, {
    id: "keating-open-tui-transcript-scroll",
    flexGrow: 1,
    width: "100%",
    border: true,
    borderStyle: "single",
    borderColor: "#4c463d",
    padding: 1,
    scrollY: true,
    stickyScroll: true,
    stickyStart: "bottom",
  });
  const transcript = new TextRenderable(renderer, {
    id: "keating-open-tui-transcript",
    content: "Ask a question, continue a learning goal, or type /shell for the classic Pi interface.",
    fg: "#eee8dc",
    width: "100%",
  });
  const inputFrame = new BoxRenderable(renderer, {
    id: "keating-open-tui-input-frame",
    width: "100%",
    height: 3,
    border: true,
    borderStyle: "single",
    borderColor: "#d6a84d",
    paddingLeft: 1,
    paddingRight: 1,
  });
  const input = new InputRenderable(renderer, {
    id: "keating-open-tui-input",
    width: "100%",
    placeholder: "Message Keating…",
    textColor: "#eee8dc",
    placeholderColor: "#81786b",
    backgroundColor: "#11100e",
    focusedBackgroundColor: "#11100e",
    focusedTextColor: "#ffffff",
  });

  scroll.add(transcript);
  inputFrame.add(input);
  shell.add(header);
  shell.add(status);
  shell.add(scroll);
  shell.add(inputFrame);
  renderer.root.add(shell);

  const turns: string[] = [];
  let streaming = "";
  let busy = false;
  let dialogCancel: (() => void) | null = null;
  const renderTranscript = () => {
    transcript.content = [...turns, streaming].filter(Boolean).join("\n\n");
    scroll.scrollTo({ y: scroll.scrollHeight, x: 0 });
  };
  const appendTurn = (message: string) => {
    turns.push(message);
    renderTranscript();
  };

  const presentSelect = (title: string, options: string[]): Promise<string | undefined> =>
    new Promise((resolve) => {
      const modal = new BoxRenderable(renderer, {
        id: `keating-dialog-${Date.now()}`,
        width: "100%",
        height: Math.min(Math.max(options.length + 4, 6), 16),
        flexDirection: "column",
        border: true,
        borderStyle: "single",
        borderColor: "#d6a84d",
        padding: 1,
      });
      const titleView = new TextRenderable(renderer, { content: `${title}  ·  Esc cancels`, fg: "#d6a84d", height: 1 });
      const select = new SelectRenderable(renderer, {
        id: `keating-select-${Date.now()}`,
        flexGrow: 1,
        options: options.map((option) => ({ name: option, description: "", value: option })),
        showDescription: false,
        wrapSelection: true,
        selectedBackgroundColor: "#d6a84d",
        selectedTextColor: "#11100e",
      });
      modal.add(titleView);
      modal.add(select);
      shell.add(modal, 3);
      let done = false;
      const finish = (value?: string) => {
        if (done) return;
        done = true;
        dialogCancel = null;
        shell.remove(modal);
        renderer.focusRenderable(input);
        resolve(value);
      };
      dialogCancel = () => finish(undefined);
      select.on(SelectRenderableEvents.ITEM_SELECTED, () => finish(select.getSelectedOption()?.value as string | undefined));
      renderer.focusRenderable(select);
    });

  const presentTextInput = (title: string, prefill?: string, placeholder?: string): Promise<string | undefined> =>
    new Promise((resolve) => {
      status.content = `${title}  ·  Enter submits  ·  Esc cancels`;
      input.value = prefill ?? "";
      input.placeholder = placeholder ?? "Type a response…";
      const previousSubmit = input.onSubmit;
      let done = false;
      const finish = (value?: string) => {
        if (done) return;
        done = true;
        dialogCancel = null;
        input.onSubmit = previousSubmit;
        input.placeholder = "Message Keating…";
        input.value = "";
        status.content = "Ready  ·  /shell switches to classic Pi  ·  Ctrl+C exits";
        resolve(value);
      };
      dialogCancel = () => finish(undefined);
      input.onSubmit = () => finish(input.value);
      renderer.focusRenderable(input);
    });

  const surface: HostSurface = {
    appendTurn,
    setStreaming(text) { streaming = text ?? ""; renderTranscript(); },
    setStatus(text) { status.content = text; },
    setBusy(value) {
      busy = value;
      status.content = value
        ? "Keating is thinking…  ·  Enter queues a follow-up"
        : "Ready  ·  /shell switches to classic Pi  ·  Ctrl+C exits";
    },
    setEditorText(text) { input.value = text; },
    setWidget(key, lines, placement) {
      if (lines?.length) appendTurn(`[${key}${placement ? ` · ${placement}` : ""}]\n${lines.join("\n")}`);
    },
    setTitle(title) { header.content = title; },
    presentSelect,
    presentConfirm(title, message) { return presentSelect(`${title}\n${message}`, ["Yes", "No"]).then((value) => value === undefined ? undefined : value === "Yes"); },
    presentInput(title, placeholder) { return presentTextInput(title, undefined, placeholder); },
    presentEditor(title, prefill) { return presentTextInput(title, prefill, "Edit response…"); },
  };
  const controller = new HostController(client, surface);
  controller.attach();

  const submit = async (raw: string) => {
    const message = raw.trim();
    if (!message) return;
    input.value = "";
    if (message === "/shell") {
      settled = true;
      settle?.("shell");
      renderer.destroy();
      await client.stop();
      return;
    }
    turns.push(`You\n${message}`);
    renderTranscript();
    try {
      if (busy) await client.followUp(message);
      else await client.prompt(message);
    } catch (error) {
      appendTurn(`[Keating] ${error instanceof Error ? error.message : String(error)}`);
    }
  };

  input.onSubmit = () => { void submit(input.value); };
  renderer.keyInput.on("keypress", (key) => {
    if (key.name === "escape" && dialogCancel) {
      key.preventDefault();
      dialogCancel();
    }
  });
  renderer.focusRenderable(input);
  renderer.start();
  if (initialPrompt?.trim()) void submit(initialPrompt);

  return result;
}
import { toolResultCardLines } from "../core/cards.js";

/**
 * Renderer-free controller for RPC hosts. Translates pi RPC events into
 * calls on a HostSurface, and services extension UI requests (select,
 * confirm, input, editor) by presenting them through the surface and
 * sending extension_ui_response commands back. The OpenTUI host implements
 * HostSurface with real widgets; tests implement it with scripted answers.
 */

export interface HostSurface {
  /** Append a completed transcript entry (user turn, assistant turn, notice, or card). */
  appendTurn(text: string): void;
  /** Replace the in-progress streaming assistant text (null clears it). */
  setStreaming(text: string | null): void;
  setStatus(text: string): void;
  setBusy(busy: boolean): void;
  setEditorText(text: string): void;
  setWidget(key: string, lines: string[] | undefined, placement?: string): void;
  setTitle(title: string): void;
  /** Resolve with the chosen option string, or undefined when cancelled. */
  presentSelect(title: string, options: string[]): Promise<string | undefined>;
  /** Resolve with the decision, or undefined when cancelled. */
  presentConfirm(title: string, message: string): Promise<boolean | undefined>;
  presentInput(title: string, placeholder?: string): Promise<string | undefined>;
  presentEditor(title: string, prefill?: string): Promise<string | undefined>;
}

export interface HostClientLike {
  onEvent(listener: (event: unknown) => void): unknown;
}

interface UiRequestEvent {
  type: "extension_ui_request";
  id?: string;
  method?: string;
  title?: string;
  options?: string[];
  message?: string;
  placeholder?: string;
  prefill?: string;
  statusText?: string;
  text?: string;
  widgetKey?: string;
  widgetLines?: string[];
  widgetPlacement?: string;
  document?: unknown;
}

function messageText(message: unknown): string {
  const content = (message as { content?: unknown } | null)?.content;
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .map((part) => {
      if (!part || typeof part !== "object") return "";
      const candidate = part as { type?: string; text?: string };
      return candidate.type === "text" && typeof candidate.text === "string" ? candidate.text : "";
    })
    .filter(Boolean)
    .join("\n");
}

function briefArgs(args: unknown): string {
  if (!args || typeof args !== "object") return "";
  const entries = Object.entries(args as Record<string, unknown>)
    .filter(([, value]) => typeof value === "string" || typeof value === "number" || typeof value === "boolean")
    .slice(0, 3)
    .map(([key, value]) => {
      const text = String(value);
      return `${key}=${text.length > 40 ? `${text.slice(0, 40)}…` : text}`;
    });
  return entries.join(", ");
}

export class HostController {
  private client: HostClientLike;
  private surface: HostSurface;
  /** Serializes UI requests: pi awaits each dialog, but never assume only one is outstanding. */
  private uiQueue: Promise<void> = Promise.resolve();

  constructor(client: HostClientLike, surface: HostSurface) {
    this.client = client;
    this.surface = surface;
  }

  attach(): void {
    this.client.onEvent((event) => this.handleEvent(event));
  }

  private async sendUiResponse(requestId: string, response: Record<string, unknown>): Promise<void> {
    const internal = this.client as unknown as { send(command: Record<string, unknown>): Promise<unknown> };
    await internal.send({ type: "extension_ui_response", id: requestId, ...response });
  }

  handleEvent(event: unknown): void {
    const candidate = event as { type?: string } | null;
    if (!candidate || typeof candidate !== "object") return;

    switch (candidate.type) {
      case "message_update": {
        const message = (event as { message?: { role?: string } }).message;
        if (message?.role === "assistant") {
          const text = messageText(message);
          if (text) this.surface.setStreaming(`Keating\n${text}`);
        }
        return;
      }
      case "message_end": {
        const message = (event as { message?: { role?: string } }).message;
        if (message?.role === "assistant") {
          this.surface.setStreaming(null);
          const text = messageText(message);
          if (text) this.surface.appendTurn(`Keating\n${text}`);
        }
        return;
      }
      case "tool_execution_start": {
        const { toolName, args } = event as { toolName?: string; args?: unknown };
        if (toolName) {
          const summary = briefArgs(args);
          this.surface.appendTurn(`→ ${toolName}${summary ? `(${summary})` : ""}`);
        }
        return;
      }
      case "tool_execution_end": {
        const { toolName, result, isError } = event as { toolName?: string; result?: unknown; isError?: boolean };
        if (!toolName) return;
        if (isError) return;
        const card = toolResultCardLines(toolName, result);
        if (card) this.surface.appendTurn(card.join("\n"));
        return;
      }
      case "agent_start":
        this.surface.setBusy(true);
        return;
      case "agent_end":
        this.surface.setBusy(false);
        return;
      case "extension_ui_request":
        this.handleUiRequest(event as UiRequestEvent);
        return;
      case "ui_document": {
        const { document } = event as { document?: unknown };
        const card = toolResultCardLines("ui_document", document);
        if (card) this.surface.appendTurn(card.join("\n"));
        return;
      }
      default:
        return;
    }
  }

  private handleUiRequest(request: UiRequestEvent): void {
    switch (request.method) {
      case "notify":
        if (request.message) this.surface.appendTurn(`[Keating] ${request.message}`);
        return;
      case "setStatus":
        this.surface.setStatus(request.statusText || "Ready");
        return;
      case "set_editor_text":
        if (typeof request.text === "string") this.surface.setEditorText(request.text);
        return;
      case "setWidget":
        if (request.widgetKey) this.surface.setWidget(request.widgetKey, request.widgetLines, request.widgetPlacement);
        return;
      case "setTitle":
        if (request.title) this.surface.setTitle(request.title);
        return;
      case "select":
      case "confirm":
      case "input":
      case "editor":
        if (request.id) this.enqueueDialog(request as UiRequestEvent & { id: string });
        return;
      default:
        this.surface.appendTurn(`[Keating] Unsupported Pi UI request${request.method ? `: ${request.method}` : ""}. The request was cancelled explicitly.`);
        if (request.id) {
          void this.sendUiResponse(request.id, { cancelled: true, reason: "unsupported_ui_request" }).catch((error) => {
            this.surface.appendTurn(`[Keating] Could not answer UI request: ${error instanceof Error ? error.message : String(error)}`);
          });
        }
        return;
    }
  }

  private enqueueDialog(request: UiRequestEvent & { id: string }): void {
    this.uiQueue = this.uiQueue
      .then(() => this.presentDialog(request))
      .catch((error) => {
        this.surface.appendTurn(`[Keating] UI request failed: ${error instanceof Error ? error.message : String(error)}`);
      });
  }

  private async presentDialog(request: UiRequestEvent & { id: string }): Promise<void> {
    const title = request.title ?? "";
    try {
      switch (request.method) {
        case "select": {
          const value = await this.surface.presentSelect(title, request.options ?? []);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        case "confirm": {
          const confirmed = await this.surface.presentConfirm(title, request.message ?? "");
          await this.sendUiResponse(request.id, confirmed === undefined ? { cancelled: true } : { confirmed });
          return;
        }
        case "input": {
          const value = await this.surface.presentInput(title, request.placeholder);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        case "editor": {
          const value = await this.surface.presentEditor(title, request.prefill);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        default:
          await this.sendUiResponse(request.id, { cancelled: true });
      }
    } catch (error) {
      await this.sendUiResponse(request.id, { cancelled: true }).catch(() => {});
      throw error;
    }
  }
}
import type { JsonValue, UiDocument } from "./types.js";

function text(value: JsonValue | undefined): string { return typeof value === "string" ? value : ""; }
function list(value: JsonValue | undefined): Array<Record<string, JsonValue>> {
  return Array.isArray(value) ? value.filter((item): item is Record<string, JsonValue> => !!item && typeof item === "object" && !Array.isArray(item)) : [];
}

export interface UiDocumentPresentation { heading: string; body: string[] }

export function uiDocumentPresentation(document: UiDocument): UiDocumentPresentation {
  const p = document.payload;
  switch (document.kind) {
    case "quiz":
      return { heading: document.title ?? `Quiz: ${text(p.topic) || "Quiz"}`, body: list(p.questions).map((q, i) => `${i + 1}. ${text(q.prompt) || text(q.question) || "Question"}`) };
    case "question":
      return { heading: document.title ?? "Question", body: list(p.fields).map((q, i) => `${i + 1}. ${text(q.prompt) || text(q.question) || "Question"}`) };
    case "goal": {
      const steps = list(p.steps).map((step) => `${text(step.status) === "done" ? "[x]" : "[ ]"} ${text(step.title)}`);
      return { heading: document.title ?? `Goal: ${text(p.title) || "Learning goal"}`, body: [text(p.description), ...steps].filter(Boolean) };
    }
    case "deck":
      return { heading: document.title ?? (text(p.title) || "Flashcards"), body: list(p.cards).flatMap((card, i) => [`${i + 1}. ${text(card.front)}`, `   ${text(card.back)}`]) };
    case "image":
      return { heading: document.title ?? (text(p.title) || "Image"), body: [text(p.alt), text(p.url) || text(p.dataUrl) || "(image data unavailable in terminal)"].filter(Boolean) };
    case "scene":
      return { heading: document.title ?? `Scene${text(p.topic) ? `: ${text(p.topic)}` : ""}`, body: [text(p.summary), text(p.storyboard), text(p.body), text(p.markdown)].filter(Boolean) };
    case "artifact":
      return { heading: document.title ?? (text(p.label) || "Artifact"), body: [text(p.summary), text(p.uri) || text(p.filePath), text(p.content)].filter(Boolean) };
    default: {
      const content = text(p.content) || JSON.stringify(p.data ?? p, null, 2);
      return { heading: document.title ?? "Tool result", body: content.split("\n") };
    }
  }
}
export const KEATING_UI_PROTOCOL = "keating.ui" as const;
export const KEATING_UI_VERSION = 1 as const;

export type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };
export type UiDocumentKind = "quiz" | "question" | "goal" | "deck" | "image" | "scene" | "artifact" | "generic";

export interface UiActionDefinition {
  id: string;
  kind: string;
  label: string;
  description?: string;
  destructive?: boolean;
  disabled?: boolean;
  input?: Record<string, JsonValue>;
}

export interface UiDocument {
  protocol: typeof KEATING_UI_PROTOCOL;
  version: typeof KEATING_UI_VERSION;
  id: string;
  revision: number;
  kind: UiDocumentKind;
  title?: string;
  status?: "active" | "submitted" | "completed" | "disabled" | "error";
  actions?: UiActionDefinition[];
  payload: Record<string, JsonValue>;
}

export interface UiActionRequest {
  protocol: typeof KEATING_UI_PROTOCOL;
  version: typeof KEATING_UI_VERSION;
  id: string;
  documentId: string;
  documentRevision: number;
  actionId: string;
  createdAt: string;
  payload: Record<string, JsonValue>;
}
import { KEATING_UI_PROTOCOL, KEATING_UI_VERSION, type JsonValue, type UiDocument, type UiDocumentKind } from "./types.js";

const KINDS = new Set<UiDocumentKind>(["quiz", "question", "goal", "deck", "image", "scene", "artifact", "generic"]);

function record(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function json(value: unknown): JsonValue {
  try { return JSON.parse(JSON.stringify(value)) as JsonValue; }
  catch { return String(value); }
}

export function isUiDocument(value: unknown): value is UiDocument {
  const item = record(value);
  return item.protocol === KEATING_UI_PROTOCOL
    && item.version === KEATING_UI_VERSION
    && typeof item.id === "string"
    && Number.isSafeInteger(item.revision)
    && KINDS.has(item.kind as UiDocumentKind)
    && !!item.payload && typeof item.payload === "object" && !Array.isArray(item.payload);
}

function inferredKind(toolName: string, details: Record<string, unknown>): UiDocumentKind {
  if (toolName === "quiz" || toolName === "grade_quiz" || details.quiz) return "quiz";
  if (toolName === "ask_user_question" || details.question || details.questions) return "question";
  if (details.goal || details.goals) return "goal";
  if (toolName === "deck" || details.deck || details.cards) return "deck";
  if (toolName === "generate_image" || details.image || details.imageUrl || details.dataUrl) return "image";
  if (toolName === "scene" || toolName === "animate" || details.scene || details.storyboard) return "scene";
  if (details.uri || details.filePath || /^(plan|map|verify)$/.test(toolName)) return "artifact";
  return "generic";
}

/** Convert tool/RPC payloads into the same wire shape used by the browser UI protocol. */
export function toolResultToUiDocument(toolName: string, result: unknown): UiDocument {
  const outer = record(result);
  if (isUiDocument(outer.uiDocument)) return outer.uiDocument;
  if (isUiDocument(result)) return result;
  const details = record(outer.details ?? result);
  const kind = inferredKind(toolName, details);
  let payload: Record<string, JsonValue>;
  if (kind === "quiz") payload = json(record(details.quiz ?? details)) as Record<string, JsonValue>;
  else if (kind === "question") payload = json(record(details.question ?? details)) as Record<string, JsonValue>;
  else if (kind === "goal") payload = json(record(details.goal ?? details)) as Record<string, JsonValue>;
  else if (kind === "deck") payload = json(record(details.deck ?? details)) as Record<string, JsonValue>;
  else if (kind === "image") payload = json(record(details.image ?? details)) as Record<string, JsonValue>;
  else if (kind === "scene") payload = json(record(details.scene ?? details)) as Record<string, JsonValue>;
  else if (kind === "artifact") payload = json(details) as Record<string, JsonValue>;
  else payload = { format: "json", data: json(details), originalKind: toolName };
  return { protocol: KEATING_UI_PROTOCOL, version: KEATING_UI_VERSION, id: String(details.id ?? `${toolName}-result`), revision: 0, kind, payload };
}
import { describe, expect, test } from "bun:test";

import { cardLines, toolResultCardLines } from "../src/core/cards.js";
import { HostController, type HostSurface } from "../src/tui/host-controller.js";

function deferredTick(): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, 0));
}

function harness() {
  let listener: ((event: unknown) => void) | undefined;
  const sent: Array<Record<string, unknown>> = [];
  const turns: string[] = [];
  const client = {
    onEvent(next: (event: unknown) => void) { listener = next; },
    async send(command: Record<string, unknown>) { sent.push(command); },
  };
  const surface: HostSurface = {
    appendTurn(text) { turns.push(text); },
    setStreaming() {},
    setStatus() {},
    setBusy() {},
    setEditorText() {},
    setWidget() {},
    setTitle() {},
    async presentSelect(_title, options) { return options.at(-1); },
    async presentConfirm() { return true; },
    async presentInput() { return "typed"; },
    async presentEditor() { return undefined; },
  };
  const controller = new HostController(client, surface);
  controller.attach();
  return { emit: (event: unknown) => listener?.(event), sent, turns };
}

describe("OpenTUI host controller", () => {
  test("answers RPC dialogs instead of cancelling Pi extension UI", async () => {
    const h = harness();
    h.emit({ type: "extension_ui_request", id: "s", method: "select", title: "Pick", options: ["a", "b"] });
    h.emit({ type: "extension_ui_request", id: "i", method: "input", title: "Why?" });
    h.emit({ type: "extension_ui_request", id: "e", method: "editor", title: "Edit" });
    await deferredTick();

    expect(h.sent).toEqual([
      { type: "extension_ui_response", id: "s", value: "b" },
      { type: "extension_ui_response", id: "i", value: "typed" },
      { type: "extension_ui_response", id: "e", cancelled: true },
    ]);
  });

  test("turns finished tool results into generative cards", () => {
    const h = harness();
    h.emit({
      type: "tool_execution_end",
      toolName: "set_learner_goal",
      result: { details: { goal: { title: "Calculus", status: "active", steps: [{ order: 0, title: "Limits", status: "in_progress" }] } } },
      isError: false,
    });
    expect(h.turns.join("\n")).toContain("Goal: Calculus");
    expect(h.turns.join("\n")).toContain("Limits");
  });

  test("explicitly answers unsupported custom UI requests", async () => {
    const h = harness();
    h.emit({ type: "extension_ui_request", id: "custom-1", method: "custom", title: "Rich form" });
    await deferredTick();
